import React, { useState, useEffect, useRef } from 'react';
import { 
  Snackbar, 
  Button, 
  Alert, 
  Box, 
  Typography, 
  LinearProgress,
  Fade,
  IconButton,
  TextField,
  Popover,
} from '@mui/material';
import DoneIcon from '@mui/icons-material/Done';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';
import CloseIcon from '@mui/icons-material/Close';
import LoopIcon from '@mui/icons-material/Loop';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import logo from '../../assets/logo512.png';
import { getBibleBookChapters } from '../../utils/bibleUtils';
import { markChapterAsRead, getReadingProgress, getReadingStreak } from '../../services/readingService';
import Cookies from 'js-cookie';
import { useTranslation } from '../../hooks/useTranslation';
import { translateBookName } from '../../utils/bookTranslations';
import successAnimation from '../../assets/animations/Success.lottie';
import angelHaloAnimation from '../../assets/animations/angel-halo.lottie';

interface ReadingProgressToastProps {
  // These props should be available in Dashboard.tsx
  book: string;
  chapter: number;
  wpToken: string;
  // Add this prop to determine if the change came from pagination or search
  isPaginationChange?: boolean;
  // Optional callback for when a chapter is marked as read
  onChapterMarkedAsRead?: (book: string, chapter: number) => void;
  user?: any;
  /** Persist WordPress app password (from welcome email) after user enters it in the streak toast. */
  setWpToken?: (token: string | null) => void;
}

const ReadingProgressToast: React.FC<ReadingProgressToastProps> = ({ 
  book = "", 
  chapter, 
  wpToken,
  isPaginationChange = false,
  user,
  onChapterMarkedAsRead,
  setWpToken,
}) => {
  const { t, language } = useTranslation();
  const [DotLottieComponent, setDotLottieComponent] = useState<React.ComponentType<{
    src?: string;
    loop?: boolean;
    autoplay?: boolean;
    style?: React.CSSProperties;
  }> | null>(null);
  
  // If book is empty, use a default book for progress display
  const effectiveBook = book === "" ? "genesis" : book;
  // Start with toast closed, we'll open it only on navigation
  const [open, setOpen] = useState(false);
  // Track if we're showing the previous page's completion prompt
  const [showingPreviousPagePrompt, setShowingPreviousPagePrompt] = useState(false);
  const [showChapterComplete, setShowChapterComplete] = useState(false);

  const [animationKey, setAnimationKey] = useState(0);
  const [showBookComplete, setShowBookComplete] = useState(false);
  const [hasShownAnimationForChapter, setHasShownAnimationForChapter] = useState<Record<string, boolean>>({});
  const [chaptersRead, setChaptersRead] = useState<Record<string, number[]>>({});
  // Reading streak state
  const [currentStreak, setCurrentStreak] = useState(0);
  const [streakLoadFailed, setStreakLoadFailed] = useState(false);
  const [streakSyncDismissed, setStreakSyncDismissed] = useState(false);
  const [syncPassword, setSyncPassword] = useState('');
  const [syncError, setSyncError] = useState('');
  const [streakInfoAnchor, setStreakInfoAnchor] = useState<HTMLElement | null>(null);
  const [showSignupCelebration, setShowSignupCelebration] = useState(false);
  const [signupCelebrationKey, setSignupCelebrationKey] = useState(0);

  const effectiveWpToken = wpToken || Cookies.get('wpToken') || '';
  const showStreakSyncPrompt =
    !!user &&
    !streakSyncDismissed &&
    (!effectiveWpToken || streakLoadFailed);
  
  // Flag to track if this is the initial load
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  
  // Track previous chapters read to prevent progress bar flashing
  const previousChaptersReadRef = useRef<Record<string, number[]>>({});
  
  // Fetch initial reading progress when component mounts or wpToken changes
  const [apiAvailable, setApiAvailable] = useState(true);
  const [isLoading, setIsLoading] = useState(true);
  
  // Maintain a cached state of reading progress to avoid flickering between page changes
  const [cachedProgressData, setCachedProgressData] = useState<Record<string, number[]>>({});
  
  // Track previous book/chapter to detect pagination changes
  const prevBookRef = useRef('');
  const prevChapterRef = useRef(0);
  
  // Get the total chapters in the current book - ensure book is lowercase AND properly trimmed
  const normalizedBook = effectiveBook.toLowerCase().trim();
  const totalChapters = getBibleBookChapters(normalizedBook);
  
  // For empty book/search, calculate overall Bible reading progress
  const [totalBibleProgress, setTotalBibleProgress] = useState(0);
  const [totalBibleChaptersRead, setTotalBibleChaptersRead] = useState(0);
  const [totalBibleChapters, setTotalBibleChapters] = useState(1189); // Total chapters in the Bible
  
  // Calculate total progress when chaptersRead changes
  useEffect(() => {
    if (Object.keys(chaptersRead).length > 0) {
      let totalRead = 0;
      Object.values(chaptersRead).forEach(chapters => {
        totalRead += chapters.length;
      });
      setTotalBibleChaptersRead(totalRead);
      setTotalBibleProgress(Math.min((totalRead / totalBibleChapters) * 100, 100));
    }
  }, [chaptersRead, totalBibleChapters]);

  // Calculate completion percentage - use book-specific or overall depending on if book is empty
  // Get chapters read for the current book, accounting for whitespace issues
  const getChaptersReadForBook = (bookName: string, progressData: Record<string, number[]>) => {
    if (!bookName || !progressData) return 0;
    const trimmedName = bookName.trim();
    
    // Try direct lookup
    if (progressData[trimmedName]?.length) {
      return progressData[trimmedName].length;
    }
    
    // Try case-insensitive lookup
    const bookKeys = Object.keys(progressData);
    for (const key of bookKeys) {
      if (key.toLowerCase().trim() === trimmedName) {
        return progressData[key].length;
      }
    }
    
    return 0;
  };
  
  // Get chapters read count for the current book
  const chaptersReadCount = getChaptersReadForBook(normalizedBook, chaptersRead) || 
                            getChaptersReadForBook(normalizedBook, previousChaptersReadRef.current) || 0;
  
  // Enhanced calculation to prevent flickering to 0
  const completionPercentage = book === "" ? 
    totalBibleProgress :
    chaptersReadCount > 0 ? 
      Math.min((chaptersReadCount / totalChapters) * 100, 100) : 0;
  
  // Check if the current chapter is already marked as read - using normalized book name
  // This function handles both direct and capitalized book names
  const checkIfChapterRead = () => {
    if (!chaptersRead || !chapter) return false;
    
    // Try with normalized book name (lowercase)
    if (chaptersRead[normalizedBook]?.includes(chapter)) return true;
    
    // Also check with capitalized first letter (Genesis vs genesis)
    const capitalizedBook = normalizedBook.charAt(0).toUpperCase() + normalizedBook.slice(1);
    if (chaptersRead[capitalizedBook]?.includes(chapter)) return true;
    
    // Try with all variations of whitespace
    const allBookKeys = Object.keys(chaptersRead);
    for (const key of allBookKeys) {
      if (key.toLowerCase().trim() === normalizedBook && chaptersRead[key]?.includes(chapter)) {
        return true;
      }
    }
    
    return false;
  };
  
  const isChapterRead = checkIfChapterRead();
  
  // Store reading progress in localStorage as a backup cache
  useEffect(() => {
    // Only store when we have non-empty data
    if (Object.keys(chaptersRead).length > 0) {
      try {
        localStorage.setItem('readingProgressCache', JSON.stringify(chaptersRead));
        
      } catch (e) {
        console.error('Failed to save reading progress to localStorage:', e);
      }
    }
  }, [chaptersRead]);
  
  // Initialize from localStorage cache on component mount
  useEffect(() => {
    try {
      const cachedData = localStorage.getItem('readingProgressCache');
      if (cachedData) {
        const parsedData = JSON.parse(cachedData);
        if (Object.keys(parsedData).length > 0) {
          // console.log('Initializing from localStorage cache:', Object.keys(parsedData));
          setCachedProgressData(parsedData);
          setChaptersRead(parsedData);
        }
      }
    } catch (e) {
      console.error('Failed to load reading progress from localStorage:', e);
    }
  }, []);

  
  // Fetch reading streak data
  const fetchReadingStreak = async () => {
    try {
      const token = wpToken || Cookies.get('wpToken') || '';
      if (!token || !user) {
        setStreakLoadFailed(false);
        return;
      }
      const streakData = await getReadingStreak(token, user);
      if (streakData) {
        setCurrentStreak(streakData.current_streak);
        setStreakLoadFailed(false);
      } else {
        setStreakLoadFailed(true);
      }
    } catch (error) {
      console.error('Error fetching reading streak:', error);
      setStreakLoadFailed(true);
    }
  };

  useEffect(() => {
    const onSignupComplete = () => {
      setSignupCelebrationKey((k) => k + 1);
      setShowSignupCelebration(true);
      setTimeout(() => {
        setShowSignupCelebration(false);
      }, 3500);
    };
    window.addEventListener('accountSignupComplete', onSignupComplete);
    return () => window.removeEventListener('accountSignupComplete', onSignupComplete);
  }, []);
  
  // Load reading streak when component mounts
  useEffect(() => {
    void fetchReadingStreak();
  }, [wpToken, user]);

  useEffect(() => {
    if (!showStreakSyncPrompt) {
      setStreakInfoAnchor(null);
    }
  }, [showStreakSyncPrompt]);
  
  useEffect(() => {
    // On first mount, set initial load flag
    return () => {
      setIsInitialLoad(false);
    };
  }, []);

  useEffect(() => {
    if (wpToken && user) {
      // Only show loading indicator on initial load, not during navigation
      if (isInitialLoad) {
        setIsLoading(true);
      } else {
        console.log('Navigation change: skipping loading indicator');
      }

      // 1. CRITICAL: Preserve existing data during API calls
      // This ensures the progress bar doesn't reset during data fetching
      
      // First, check if we have current non-empty state
      if (Object.keys(chaptersRead).length > 0) {
        // If we already have data, save it as the source of truth
        previousChaptersReadRef.current = {...chaptersRead};
      } 
      // Next, try cached data if state is empty
      else if (Object.keys(cachedProgressData).length > 0) {
        setChaptersRead({...cachedProgressData});
        previousChaptersReadRef.current = {...cachedProgressData};
      } 
      // Finally, try localStorage as a last resort
      else {
        try {
          const cachedData = localStorage.getItem('readingProgressCache');
          if (cachedData) {
            const parsedData = JSON.parse(cachedData);
            if (Object.keys(parsedData).length > 0) {
              setChaptersRead({...parsedData});
              previousChaptersReadRef.current = {...parsedData};
            }
          }
        } catch (e) {
          console.error('Failed to use localStorage fallback:', e);
        }
      }
      
      getReadingProgress(Cookies.get("wpToken") || "", user)
        .then((progressData) => {
          // Normalize book names to lowercase
          const normalizedProgressData: Record<string, number[]> = {};
          
          // Convert all book keys to lowercase and merge any duplicate entries
          Object.entries(progressData).forEach(([bookName, chapters]) => {
            // Skip empty book names or null/undefined entries
            if (!bookName) return;
            
            const lowercaseBookName = bookName.toLowerCase();
            
            // Initialize array if needed
            if (!normalizedProgressData[lowercaseBookName]) {
              normalizedProgressData[lowercaseBookName] = [];
            }
            
            // Add chapters (ensure they're numbers)
            const chaptersToAdd = (chapters as any[]).map(ch => {
              return typeof ch === 'number' ? ch : parseInt(ch, 10);
            }).filter(ch => !isNaN(ch)); // Filter out any NaN values
            
            // Add new chapters and remove duplicates
            normalizedProgressData[lowercaseBookName] = [
              ...normalizedProgressData[lowercaseBookName],
              ...chaptersToAdd
            ].filter((value, index, self) => self.indexOf(value) === index); // Remove duplicates
            
            // Sort chapters numerically
            normalizedProgressData[lowercaseBookName].sort((a, b) => a - b);
          });
          
          // CRITICAL: Check if the new data has actual content before replacing current state
          // This prevents the progress bar from resetting if we get empty data from the API
          if (Object.keys(normalizedProgressData).length > 0) {
            setChaptersRead(normalizedProgressData);
            // Update cached data
            setCachedProgressData(normalizedProgressData);
            previousChaptersReadRef.current = normalizedProgressData;
          } else if (Object.keys(previousChaptersReadRef.current).length > 0) {
            // If API returned empty data but we have previous data, keep using that
            setChaptersRead(previousChaptersReadRef.current);
          }
          
          setApiAvailable(true);
          
          // Check if current chapter is marked as read - using normalized book name
          const normalizedCurrentBook = effectiveBook.toLowerCase();
          const currentBookProgress = normalizedProgressData[normalizedCurrentBook] || [];
          
          // Only show the completion animation briefly when loading an already-read chapter
          // But only if we haven't already shown it for this chapter
          const chapterKey = `${normalizedCurrentBook}-${chapter}`;
          if (currentBookProgress.includes(chapter) && !hasShownAnimationForChapter[chapterKey]) {
            setHasShownAnimationForChapter(prev => ({ ...prev, [chapterKey]: true }));
            setAnimationKey(prev => prev + 1); // Force animation to replay
            setShowChapterComplete(true);
            // Reset after a delay (3 seconds so user can see the success)
            setTimeout(() => {
              setShowChapterComplete(false);
            }, 3000);
          }
        })
        .catch(err => {
          console.error('Error fetching reading progress:', err);
          setApiAvailable(false);
        })
        .finally(() => {
          setIsLoading(false);
        });
    }
  }, [book, chapter, user, wpToken]);
  
  // Listen for chapterMarkedAsRead events from the flame icon
  useEffect(() => {
    const handleChapterMarkedAsRead = (event: CustomEvent) => {
      const { book: markedBook, chapter: markedChapter } = event.detail;
      const normalizedBook = markedBook?.toLowerCase().trim();
      const currentBookNormalized = effectiveBook.toLowerCase().trim();
      
      console.log('Chapter marked as read event received:', {
        markedBook: normalizedBook,
        markedChapter,
        currentBook: currentBookNormalized,
        currentChapter: chapter,
        matches: normalizedBook === currentBookNormalized && markedChapter === chapter
      });
      
      // Show animation if chapter matches - book matching is secondary since book prop might be empty
      const chapterMatches = markedChapter === chapter;
      // Book matches if: exact match, or current book is empty (showing all books), or marked book matches current
      const bookMatches = normalizedBook === currentBookNormalized || book === "" || effectiveBook === "" || currentBookNormalized === "genesis";
      
      // Always show animation if chapter matches (most important check)
      if (chapterMatches) {
        console.log('Showing chapter complete animation');
        // Reset userClosed flag when a new chapter is marked
        setUserClosed(false);
        // Show the toast
        setOpen(true);
        // Trigger chapter complete animation
        setAnimationKey(prev => prev + 1); // Force animation to replay
        setShowChapterComplete(true);
        setTimeout(() => {
          setShowChapterComplete(false);
        }, 3000);
        
        // Refresh reading progress to update the UI (but don't trigger animation again)
        if (wpToken && user) {
          getReadingProgress(wpToken, user)
            .then(progress => {
              setChaptersRead(progress);
              setCachedProgressData(progress);
              localStorage.setItem('readingProgressCache', JSON.stringify(progress));
              // Don't trigger animation here - it's already been shown above
            })
            .catch(err => console.error('Error refreshing reading progress:', err));
        }
      } else {
        console.log('Event received but conditions not met - not showing animation');
      }
    };
    
    window.addEventListener('chapterMarkedAsRead', handleChapterMarkedAsRead as EventListener);
    
    return () => {
      window.removeEventListener('chapterMarkedAsRead', handleChapterMarkedAsRead as EventListener);
    };
  }, [effectiveBook, chapter, wpToken, user]);

  // Detect pagination changes to show the toast
  useEffect(() => {
    const isPageChange = book && 
                        chapter && 
                        (prevBookRef.current !== book || prevChapterRef.current !== chapter) &&
                        prevBookRef.current !== ''; // Ignore first load
    
    if (isPageChange) {
      
      // Reset chapter complete animation when changing pages
      setShowChapterComplete(false);
      setShowBookComplete(false);
      // Reset the animation tracking when changing pages so it can show again for new chapters
      setHasShownAnimationForChapter({});
      
      // Check if the previous chapter was read already
      const prevBookNormalized = prevBookRef.current.toLowerCase().trim();
      const prevChapterRead = chaptersRead[prevBookNormalized]?.includes(prevChapterRef.current) || false;
      
      // Only show the toast if the previous chapter was NOT marked as read
      if (!prevChapterRead && prevBookRef.current && prevChapterRef.current) {
        // Store previous page info for the toast
        setShowingPreviousPagePrompt(true);
        setOpen(true);
      } else {
        setShowingPreviousPagePrompt(false);
        setOpen(false);
      }
      
      // 2. CRITICAL: Ensure state consistency during page navigation
      // This prevents the progress bar from flickering or resetting during navigation
      
      // First try cached data which should be most up-to-date
      if (Object.keys(cachedProgressData).length > 0) {
        setChaptersRead({...cachedProgressData});
      }
      // If we somehow don't have cached data but do have previous data, use that
      else if (Object.keys(previousChaptersReadRef.current).length > 0) {
        setChaptersRead({...previousChaptersReadRef.current});
      }
    }
    
    // In debug mode, always show the toast
    // if (debugMode) {
      // Don't auto-open on page change if toast is already open or user has closed it
      if (!open && !userClosed) {
        setOpen(true);
      }
    // }
    // Normal behavior - show toast only on pagination for unread chapters when API is available
    // else if (isPageChange && isPaginationChange && !isChapterRead && apiAvailable) {
    //   setOpen(true);
    // }
    
    // Update refs
    prevBookRef.current = book;
    prevChapterRef.current = chapter;
  }, [book, chapter, isChapterRead, isPaginationChange, apiAvailable, cachedProgressData, chaptersRead, open]);
  
  const [userClosed, setUserClosed] = useState(false);

  // Dynamically import DotLottieReact when any Lottie UI is needed (chapter complete, signup, streak sync)
  useEffect(() => {
    const needsLottie =
      showChapterComplete || showSignupCelebration || showStreakSyncPrompt;
    if (needsLottie) {
      import('@lottiefiles/dotlottie-react').then((module) => {
        setDotLottieComponent(() => module.DotLottieReact);
      }).catch((error) => {
        console.error('Failed to load DotLottieReact:', error);
      });
    }
  }, [showChapterComplete, showSignupCelebration, showStreakSyncPrompt]);
  
  const handleClose = (event?: React.SyntheticEvent | Event, reason?: string) => {
    // Prevent closing on clickaway when reason is 'clickaway'
    if (reason === 'clickaway') {
      return;
    }
    setOpen(false);
    setUserClosed(true);
  };
  

  const handleMarkAsRead = async () => {
    // If we're showing a prompt for the previous page, mark that one instead of current page
    const bookToUse = showingPreviousPagePrompt ? prevBookRef.current : (effectiveBook || book);
    const chapterToUse = showingPreviousPagePrompt ? prevChapterRef.current : chapter;
    
    if ((!bookToUse) || !chapterToUse || !apiAvailable) return;
    
    const normalizedBookKey = bookToUse.toLowerCase().trim();
    
    // Store current state before API call to maintain consistency
    previousChaptersReadRef.current = {...chaptersRead};
    
    try {
      // Call API with normalized book name to ensure case consistency
      const success = await markChapterAsRead(normalizedBookKey, chapter, wpToken, user);
      
      if (success) {
        // Update local state with normalized book key for consistency
        setChaptersRead(prev => {
          const bookChapters = prev[normalizedBookKey] || [];
          
          if (!bookChapters.includes(chapter)) {
            const updatedState = {
              ...prev,
              [normalizedBookKey]: [...bookChapters, chapter].sort((a, b) => a - b) // Keep chapters sorted
            };
            
            // CRITICAL: Update cached state immediately to ensure UI consistency
            setCachedProgressData({...updatedState});
            
            // Also update localStorage for persistence across page reloads
            localStorage.setItem('readingProgressCache', JSON.stringify(updatedState));
            
            return updatedState;
          }
          return prev;
        });
        
        // Call the optional callback for parent components
        if (onChapterMarkedAsRead) {
          onChapterMarkedAsRead(normalizedBookKey, chapter);
        }
        
        // Refresh streak data after marking chapter as read
        fetchReadingStreak();
        
        // Make a direct API call to update the streak after a small delay to ensure reading history is updated
        // We're adding a small timeout to allow the first API call to complete and update reading history
        setTimeout(async () => {
          try {
            const streakApiUrl = `${process.env.REACT_APP_WP_API_URL?.includes('/wp/v2') 
              ? process.env.REACT_APP_WP_API_URL.replace('/wp/v2', '') 
              : process.env.REACT_APP_WP_API_URL?.includes('/wp-json') 
                ? process.env.REACT_APP_WP_API_URL.split('/wp-json')[0] + '/wp-json'
                : process.env.REACT_APP_WP_API_URL}/revelationary/v1/reading-streak`;
                
            const streakResponse = await fetch(streakApiUrl, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Basic ${btoa(`${user?.email || ''}:${wpToken}`)}`
              },
              body: JSON.stringify({
                date: new Date().toISOString().split('T')[0] // Current date in YYYY-MM-DD format
              })
            });
            
            // Check the response
            if (streakResponse.ok) {
              const streakData = await streakResponse.json();
              console.log('Streak update response:', streakData);
              
              // Refresh streak data after successful update
              fetchReadingStreak();
            } else {
              const errorData = await streakResponse.json();
              console.error('Streak update failed:', errorData);
            }
          } catch (streakError) {
            console.error('Error updating reading streak:', streakError);
          }
        }, 1000); // 1 second delay
        
        // Show chapter completion animation with timeout (3 seconds so user can see the success)
        setAnimationKey(prev => prev + 1); // Force animation to replay
        setShowChapterComplete(true);
        setTimeout(() => {
          setShowChapterComplete(false);
        }, 3000);
        
        // Check if this completes the book - use normalized book name
        const updatedChaptersInBook = [...(chaptersRead[normalizedBookKey] || []), chapter];
        if (updatedChaptersInBook.length === totalChapters) {
          // Show book completion animation
          setTimeout(() => {
            setShowBookComplete(true);
            setTimeout(() => {
              setShowBookComplete(false);
            }, 3000);
          }, 500);
        }
      } else {
        console.warn('API call to mark chapter as read was unsuccessful');
      }
    } catch (error) {
      console.error('Error marking chapter as read:', error);
    }
  };

  const handleStreakSyncSubmit = () => {
    if (!syncPassword.trim()) {
      setSyncError(String(t('readingProgress.syncPasswordRequired')));
      return;
    }
    setSyncError('');
    const passwordValue = syncPassword;
    try {
      Cookies.set('wpToken', passwordValue, {
        expires: 7,
        path: '/',
        secure: true,
        sameSite: 'strict',
      });
      setSyncPassword('');
      // Defer parent update + streak fetch to the next frame so Lottie/Snackbar unmount
      // does not run in the same ResizeObserver turn (avoids benign dev overlay errors).
      requestAnimationFrame(() => {
        setWpToken?.(passwordValue);
        setStreakLoadFailed(false);
        void fetchReadingStreak();
      });
    } catch {
      setSyncError(String(t('readingProgress.syncPasswordError')));
    }
  };
  
  return (
    <>
      <Snackbar
        key={`streak-sync-${language}`}
        open={showStreakSyncPrompt}
        autoHideDuration={null}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
        sx={{ mt: 7, zIndex: (theme) => theme.zIndex.snackbar }}
      >
        <Alert
          severity="info"
          icon={false}
          sx={{
            width: '100%',
            maxWidth: 440,
            backgroundColor: (theme) =>
              theme.palette.mode === 'light' ? '#f5f5f5' : '#2d2d2d',
            color: (theme) =>
              theme.palette.mode === 'light' ? '#212121' : '#f5f5f5',
            border: (theme) =>
              `1px solid ${theme.palette.mode === 'light' ? theme.palette.grey[700] : theme.palette.grey[800]}`,
            boxShadow: 2,
            py: 1.25,
            px: 1.25,
            alignItems: 'flex-start',
            '& .MuiAlert-message': {
              width: '100%',
              padding: 0,
              margin: 0,
            },
          }}
        >
          <>
          <Box
            sx={{
              width: '100%',
              display: 'grid',
              gridTemplateColumns: 'auto 1fr',
              gridTemplateRows: 'auto auto',
              columnGap: 1,
              rowGap: 0.75,
              alignItems: 'start',
            }}
          >
            <Box
              sx={{
                gridRow: 1,
                gridColumn: 2,
                display: 'flex',
                flexDirection: 'row',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: 0.5,
                minWidth: 0,
              }}
            >
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 0.25,
                  flexWrap: 'wrap',
                  minWidth: 0,
                  flex: 1,
                }}
              >
                            <Box
              sx={{
                gridRow: '1 / -1',
                gridColumn: 1,
                width: 56,
                height: 52,
                alignSelf: 'start',
                flexShrink: 0,
                display: 'flex',
                alignItems: 'flex-start',
                justifyContent: 'flex-start',
                p: 0,
                mt: 0,
                filter: (theme) =>
                  theme.palette.mode === 'dark'
                    ? 'brightness(0) invert(1)'
                    : 'brightness(0)',
                WebkitFilter: (theme) =>
                  theme.palette.mode === 'dark'
                    ? 'brightness(0) invert(1)'
                    : 'brightness(0)',
              }}
            >
                            {DotLottieComponent && showStreakSyncPrompt ? (
                <DotLottieComponent
                  key="streak-sync-halo"
                  src={angelHaloAnimation}
                  loop
                  autoplay
                  style={{ 
                    width: '100%', 
                    height: '100%', 
                    display: 'block',
                    marginTop: -15,
                    marginLeft: -15,
                  }}
                />
              ) : null}
               </Box>
                <Typography variant="subtitle2" fontWeight={600} component="span" style={{ marginTop: -30, marginLeft: -12 }}>
                  {String(t('readingProgress.continueStreakTitle'))}
                </Typography>
                <IconButton
                  size="small"
                  onClick={(e) => {
                    setStreakInfoAnchor((prev) =>
                      prev ? null : e.currentTarget
                    );
                  }}
                  aria-label={String(t('readingProgress.continueStreakInfoAria'))}
                  aria-expanded={Boolean(streakInfoAnchor)}
                  sx={{
                    p: 0.25,
                    color: 'text.secondary',
                    mt: -4.25,
                    flexShrink: 0,
                    '&:hover': { color: 'primary.main' },
                  }}
                >
                  <InfoOutlinedIcon sx={{ fontSize: 15 }} />
                </IconButton>
              </Box>
              <IconButton
                aria-label={String(t('common.close'))}
                size="small"
                onClick={() => {
                  setStreakSyncDismissed(true);
                }}
                sx={{
                  color: 'inherit',
                  flexShrink: 0,
                  p: 0.25,
                  mt: -4,
                  ml: 6
                }}
              >
                <CloseIcon fontSize="small" />
              </IconButton>
            </Box>
            <Box
              sx={{
                gridRow: 2,
                gridColumn: 2,
                display: 'flex',
                flexDirection: 'row',
                alignItems: 'flex-end',
                gap: 1,
                width: '100%',
                minWidth: 0,
                mb: syncError ? 0.25 : 0,
                mt: -4
              }}
            >
              <TextField
                margin="dense"
                size="small"
                type="password"
                autoComplete="current-password"
                label={String(t('readingProgress.syncPasswordLabel'))}
                value={syncPassword}
                onChange={(e) => {
                  setSyncPassword(e.target.value);
                  setSyncError('');
                }}
                sx={{
                  flex: 1,
                  minWidth: 0,
                  ml: -1,
                  mb: -0.05,
                  '& .MuiOutlinedInput-root': {
                    fontSize: '0.8125rem',
                    borderRadius: '6px',
                  },
                  '& .MuiOutlinedInput-input': {
                    py: '5px',
                    px: '10px',
                  },
                  '& .MuiInputLabel-outlined': {
                    fontSize: '0.75rem',
                    lineHeight: 1.2,
                  },
                  '& .MuiOutlinedInput-notchedOutline': {
                    borderWidth: '1px',
                  },
                }}
              />
              <IconButton
                size="small"
                onClick={handleStreakSyncSubmit}
                aria-label={String(t('readingProgress.connectAccount'))}
                sx={{
                  flexShrink: 0,
                  width: 30,
                  height: 30,
                  p: 0.5,
                  mb: 0.05,
                  borderRadius: '6px',
                  bgcolor: 'primary.main',
                  color: 'primary.contrastText',
                  '&:hover': { bgcolor: 'primary.dark' },
                }}
              >
                <LoopIcon sx={{ fontSize: 18 }} />
              </IconButton>
            </Box>
            {syncError ? (
              <Typography
                variant="caption"
                color="error"
                display="block"
                sx={{ gridRow: 3, gridColumn: 2 }}
              >
                {syncError}
              </Typography>
            ) : null}
          </Box>
          <Popover
            open={Boolean(streakInfoAnchor)}
            anchorEl={streakInfoAnchor}
            onClose={() => {
              setStreakInfoAnchor(null);
            }}
            anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
            transformOrigin={{ vertical: 'bottom', horizontal: 'left' }}
            disableRestoreFocus
            sx={{
              zIndex: (theme) => theme.zIndex.snackbar + 1,
            }}
            PaperProps={{
              sx: { maxWidth: 280, p: 1.5 },
            }}
          >
            <Typography variant="caption" color="text.secondary" component="div">
              {String(t('readingProgress.continueStreakBody'))}
            </Typography>
          </Popover>
          </>
        </Alert>
      </Snackbar>

      <Snackbar
        key={language}
        open={!!(
          open &&
          user &&
          effectiveWpToken &&
          apiAvailable &&
          !userClosed &&
          !showStreakSyncPrompt
        )}
        autoHideDuration={null}
        onClose={handleClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
        sx={{ 
          mt: 7,
          width: '100%',
          maxWidth: 400
         }} // Add margin to avoid overlap with header
      >
        <Alert 
          severity="info" 
          sx={{ 
            width: '100%',
            backgroundColor: (theme) => theme.palette.mode === 'light' ? '#FFFFFF' : '#212121',
            color: (theme) => theme.palette.mode === 'light' ? '#212121' : '#FFFFFF',
            border: (theme) =>
              `1px solid ${theme.palette.mode === 'light' ? theme.palette.grey[700] : theme.palette.grey[800]}`,
            '& .MuiAlert-icon': {
              display: 'none'
            },
            '& .MuiAlert-action': {
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              position: 'absolute',
              right: 0,
              top: 0,
              padding: '0.5rem 0 0 0',
              margin: 0,
              width: 'auto',
              height: 'auto',
              backgroundColor: 'transparent',
              '&:hover': {
                backgroundColor: 'transparent',
              }
            },
            '& .MuiAlert-message': {
              width: '100%'
            }
          }}
          action={
            <IconButton
              aria-label="close"
              color="inherit"
              size="small"
              onClick={(e) => {
                e.stopPropagation();
                handleClose(e);
              }}
              sx={{ 
                position: 'absolute',
                right: 8,
                top: 8,
                zIndex: 1,
              }}
            >
              <CloseIcon fontSize="small" sx={{ color: (theme) => theme.palette.mode === 'light' ? '#212121' : '#FFFFFF' }} />
            </IconButton>
          }
        >
          <Box sx={{ display: 'flex', flexDirection: 'column', width: '100%' }} key={language}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1, mt: 0 }}>
              <Typography variant="body1" key={language}>
                {showingPreviousPagePrompt ?
                  t('readingProgress.markPreviousAsRead', { 
                    book: translateBookName(prevBookRef.current, t), 
                    chapter: prevChapterRef.current 
                  }) :
                  (book === "" ? 
                    t('readingProgress.yourBibleReadingProgress') : 
                    t('readingProgress.markAsReadToTrack', { 
                      book: translateBookName(effectiveBook, t), 
                      chapter: chapter 
                    }))}
              </Typography>
            </Box>
              {currentStreak > 0 && (
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }} key={language}>
                  <Box
                    component="img"
                    src={logo}
                    alt="Reading streak"
                    sx={{ 
                      width: "1rem",
                      height: "1rem",
                      opacity: 0.75,
                      filter: (theme) => theme.palette.mode === "dark" ? "invert(1)" : "none",
                      objectFit: "contain",
                    }} 
                  />
                  <Typography variant="body2" sx={{ ml: 0.5 }}>
                    {t('readingProgress.dayStreak', { count: currentStreak })}
                  </Typography>
                </Box>
              )}
            
            <LinearProgress 
              variant={isLoading ? "indeterminate" : "determinate"} 
              value={completionPercentage} 
              sx={{ mb: 1, mr: 1 }}
            />
            
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
            <Typography variant="caption" key={language}>
                {t('readingProgress.chaptersRead', { count: chaptersReadCount, total: totalChapters })}
              </Typography>
              <Button 
                color="primary" 
                size="small" 
                variant="contained"
                onClick={handleMarkAsRead}
                // icon={<DoneIcon />}
                sx={{
                  mr: 0,
                  mt: 5,
                  mb: 1,
                  py: .15
                }}
              >
                <DoneIcon />
              </Button>
            </Box>
          </Box>
        </Alert>
      </Snackbar>
      
      {/* Chapter completion animation */}
      <Fade in={showChapterComplete}>
        <Box
          sx={{
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            zIndex: 9999,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            textAlign: 'center',
            p: 3,
            borderRadius: 2,
            bgcolor: 'secondary.main',
            color: 'black',
            // boxShadow: '0px 0px 20px rgba(255, 215, 0, 0.7)',
          }}
          key={`${language}-${showChapterComplete}-${chapter}`}
        >
          <Box sx={{ width: 120, height: 120, mb: 2 }}>
            {DotLottieComponent && showChapterComplete ? (
              <DotLottieComponent
                key={`lottie-${chapter}-${animationKey}`}
                src={successAnimation}
                loop={false}
                autoplay={true}
              />
            ) : (
              <DoneIcon sx={{ fontSize: 52 }} />
            )}
          </Box>
          <Typography variant="h6">
            {t('readingProgress.chapterComplete')}
          </Typography>
        </Box>
      </Fade>

      <Fade in={showSignupCelebration}>
        <Box
          sx={{
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            zIndex: 10000,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            textAlign: 'center',
            p: 3,
            borderRadius: 2,
            bgcolor: 'secondary.main',
            color: 'black',
            pointerEvents: 'none',
            boxShadow: 4,
          }}
          key={`signup-celebration-${signupCelebrationKey}-${language}`}
        >
          <Box sx={{ width: 120, height: 120, mb: 2 }}>
            {DotLottieComponent && showSignupCelebration ? (
              <DotLottieComponent
                key={`angel-halo-signup-${signupCelebrationKey}`}
                src={angelHaloAnimation}
                loop={false}
                autoplay={true}
              />
            ) : null}
          </Box>
          <Typography variant="h6">
            {t('readingProgress.welcomeAccountCreated')}
          </Typography>
        </Box>
      </Fade>
      
      {/* Book completion animation */}
      <Fade in={showBookComplete}>
        <Box
          sx={{
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            zIndex: 9999,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            textAlign: 'center',
            p: 4,
            borderRadius: 2,
            bgcolor: 'gold',
            color: 'black',
            boxShadow: '0px 0px 20px rgba(255, 215, 0, 0.7)',
          }}
          key={language}
        >
          <EmojiEventsIcon sx={{ 
            fontSize: 80, 
            mb: 1, 
            color: 'goldenrod'
          }} />
          <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
            {t('readingProgress.congratulations')}
          </Typography>
          <Typography variant="h6">
            {t('readingProgress.bookCompleted', { book: translateBookName(book, t) })}
          </Typography>
        </Box>
      </Fade>
      
      <style>{`
        @keyframes pulse {
          0% { transform: scale(1); }
          50% { transform: scale(1.2); }
          100% { transform: scale(1); }
        }
        
        @keyframes bounce {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-15px); }
        }
      `}</style>
    </>
  );
};

export default ReadingProgressToast;
